#include <stdlib.h>
#include <string.h>
#ifdef _OPENMP
#include <omp.h>
#endif

#if defined(__AVX512F__)
#define VW 16
#define MR 12
#define NV 2
#elif defined(__AVX__)
#define VW 8
#define MR 6
#define NV 2
#elif defined(__ARM_NEON) || defined(__aarch64__)
#define VW 4
#define MR 8
#define NV 3
#else
#define VW 4
#define MR 4
#define NV 2
#endif

#define NR (VW * NV)
#define KC 256

typedef float vf __attribute__((vector_size(VW * 4), aligned(VW * 4)));
typedef float vfu __attribute__((vector_size(VW * 4), aligned(4), may_alias));

static inline vf bcast(float x)
{
    vf v;
    for (int i = 0; i < VW; i++) v[i] = x;
    return v;
}

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int mr, int nr, int accum)
{
    vf acc[MR][NV];
#pragma GCC unroll 16
    for (int i = 0; i < MR; i++)
#pragma GCC unroll 4
        for (int j = 0; j < NV; j++) acc[i][j] = bcast(0.0f);

    for (int p = 0; p < kc; p++) {
        vf bv[NV];
#pragma GCC unroll 4
        for (int j = 0; j < NV; j++) bv[j] = *(const vf *)(b + p * NR + j * VW);
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            vf av = bcast(a[p * MR + i]);
#pragma GCC unroll 4
            for (int j = 0; j < NV; j++) acc[i][j] += av * bv[j];
        }
    }

    if (mr == MR && nr == NR) {
        if (accum) {
#pragma GCC unroll 16
            for (int i = 0; i < MR; i++)
#pragma GCC unroll 4
                for (int j = 0; j < NV; j++) {
                    vfu *d = (vfu *)(c + (size_t)i * ldc + j * VW);
                    *d = *d + acc[i][j];
                }
        } else {
#pragma GCC unroll 16
            for (int i = 0; i < MR; i++)
#pragma GCC unroll 4
                for (int j = 0; j < NV; j++)
                    *(vfu *)(c + (size_t)i * ldc + j * VW) = acc[i][j];
        }
    } else {
        float t[MR * NR] __attribute__((aligned(64)));
        for (int i = 0; i < MR; i++)
            for (int j = 0; j < NV; j++)
                *(vf *)(t + i * NR + j * VW) = acc[i][j];
        for (int i = 0; i < mr; i++) {
            float *d = c + (size_t)i * ldc;
            if (accum)
                for (int j = 0; j < nr; j++) d[j] += t[i * NR + j];
            else
                for (int j = 0; j < nr; j++) d[j] = t[i * NR + j];
        }
    }
}

static void pack_a(const float *A, int n, int i0, int p0, int kc, float *dst)
{
    int mr = n - i0 < MR ? n - i0 : MR;
    for (int r = 0; r < mr; r++) {
        const float *s = A + (size_t)(i0 + r) * n + p0;
        for (int p = 0; p < kc; p++) dst[p * MR + r] = s[p];
    }
    for (int r = mr; r < MR; r++)
        for (int p = 0; p < kc; p++) dst[p * MR + r] = 0.0f;
}

static void pack_b(const float *B, int n, int j0, int p0, int kc, float *dst)
{
    int nr = n - j0 < NR ? n - j0 : NR;
    for (int p = 0; p < kc; p++) {
        const float *s = B + (size_t)(p0 + p) * n + j0;
        float *d = dst + p * NR;
        int j = 0;
        for (; j < nr; j++) d[j] = s[j];
        for (; j < NR; j++) d[j] = 0.0f;
    }
}

static void *alloc64(size_t bytes)
{
    bytes = (bytes + 63) & ~(size_t)63;
    if (bytes == 0) bytes = 64;
    return aligned_alloc(64, bytes);
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int nkb = (n + KC - 1) / KC;
    int MP = (n + MR - 1) / MR;
    int NP = (n + NR - 1) / NR;

    float *Ap = alloc64((size_t)nkb * MP * KC * MR * sizeof(float));
    float *Bp = alloc64((size_t)nkb * NP * KC * NR * sizeof(float));

    int nt = 1;
#ifdef _OPENMP
    nt = omp_get_max_threads();
#endif

    int mcp = 96 / MR;
    if (mcp < 1) mcp = 1;
    int ncp = 256 / NR;
    if (ncp < 1) ncp = 1;
    for (;;) {
        long items = (long)((MP + mcp - 1) / mcp) * ((NP + ncp - 1) / ncp);
        if (items >= 3L * nt || (mcp == 1 && ncp == 1)) break;
        if (ncp >= mcp && ncp > 1) ncp = (ncp + 1) / 2;
        else mcp = (mcp + 1) / 2;
    }
    int mblocks = (MP + mcp - 1) / mcp;
    int nblocks = (NP + ncp - 1) / ncp;
    int nitems = mblocks * nblocks;

#pragma omp parallel
    {
#pragma omp for schedule(static) nowait
        for (int t = 0; t < nkb * MP; t++) {
            int kb = t / MP, ip = t % MP;
            int p0 = kb * KC;
            int kc = n - p0 < KC ? n - p0 : KC;
            pack_a(A, n, ip * MR, p0, kc, Ap + (size_t)t * KC * MR);
        }
#pragma omp for schedule(static)
        for (int t = 0; t < nkb * NP; t++) {
            int kb = t / NP, jp = t % NP;
            int p0 = kb * KC;
            int kc = n - p0 < KC ? n - p0 : KC;
            pack_b(B, n, jp * NR, p0, kc, Bp + (size_t)t * KC * NR);
        }

#pragma omp for schedule(dynamic, 1)
        for (int it = 0; it < nitems; it++) {
            int mb = it % mblocks, nb = it / mblocks;
            int ip0 = mb * mcp, ip1 = ip0 + mcp < MP ? ip0 + mcp : MP;
            int jp0 = nb * ncp, jp1 = jp0 + ncp < NP ? jp0 + ncp : NP;
            for (int kb = 0; kb < nkb; kb++) {
                int p0 = kb * KC;
                int kc = n - p0 < KC ? n - p0 : KC;
                for (int jp = jp0; jp < jp1; jp++) {
                    int j0 = jp * NR;
                    int nr = n - j0 < NR ? n - j0 : NR;
                    const float *bp = Bp + ((size_t)kb * NP + jp) * KC * NR;
                    for (int ip = ip0; ip < ip1; ip++) {
                        int i0 = ip * MR;
                        int mr = n - i0 < MR ? n - i0 : MR;
                        const float *ap = Ap + ((size_t)kb * MP + ip) * KC * MR;
                        kernel(kc, ap, bp, C + (size_t)i0 * n + j0, n, mr, nr, kb > 0);
                    }
                }
            }
        }
    }

    free(Ap);
    free(Bp);
}
